async function sendToChatScoreAgent(url, input) {
  try {
    Logger.info(
      `sendToChatScoreAgent REST CALL initiation: URL: -- ${url} INPUT: -- ${JSON.stringify(input)}`
    );
    const { brand, ...payload } = input;

    // Langfuse Credentials for Review Toolkit
    const langfusePublicKey = process.env.LANGFUSE_PK;
    const langfuseSecretKey = process.env.LANGFUSE_SK;

    const response = await axios({
      method: 'post',
      url: url,
      headers: {
        'Content-Type': 'application/json',
        Authorization: `Basic ${btoa(langfusePublicKey + ':' + langfuseSecretKey)}`
      },
      data: payload
    });
    Logger.info(`sendToChatScoreAgent RESPONSE: -- response: -- ${response}`);
    return response.data;
  } catch (error) {
    const customError = createCustomError(
      error,
      'sendToChatScoreAgent',
      `sendToChatScoreAgent ERROR: -- ${error.message} FOR URL: -- ${url} INPUT: -- ${JSON.stringify(input)}`,
      ERROR_CODE?.P2_ERROR_UPDATING_CHAT_SCORE?.errorCode,
      ERROR_CODE?.P2_ERROR_UPDATING_CHAT_SCORE?.statusCode
    );
    // Handle any errors that occur during the HTTP request
    Logger.error(errorSerializer(customError));
  }
  return null;
}

