async function sendQueryToFlowise(url, query, sessionID, brand) {
  try {
    // Check if the brand is valid
    const startTime = Date.now();
    if (!validBrands.includes(brand)) {
      const errorObject = new Error(`Invalid brand: ${brand}. Must be one of: ${validBrands.join(', ')}`);
      const customError = createCustomError(
        errorObject,
        'sendQueryToFlowise',
        `Invalid brand: ${brand}. Must be one of: ${validBrands.join(', ')}`,
        ERROR_CODE?.P3_INVALID_BRAND?.errorCode,
        ERROR_CODE?.P3_INVALID_BRAND?.statusCode
      );
      Logger.error(errorSerializer(customError));
      return {
        error: `Invalid brand: ${brand}. Must be one of: ${validBrands.join(', ')}`
      };
    }

    // read the brand appropriate system message prompt
    let flowiseOverrideObject = {};
    try {
      const { getOverrides } = await import(`../config/overrides/${brand}`);
      flowiseOverrideObject = await getOverrides(brand);
    } catch (error) {
      const customError = createCustomError(
        error,
        'flowiseOverrideObject',
        `Error importing configuration for brand: ${brand}`,
        ERROR_CODE?.P1_ERROR_CONFIGURING_BRAND?.errorCode,
        ERROR_CODE?.P1_ERROR_CONFIGURING_BRAND?.statusCode
      );

      Logger.error(errorSerializer(customError));
      return { error: `Error importing configuration for brand: ${brand}` };
    }

    const flowiseData = {
      question: query,
      overrideConfig: {
        sessionId: sessionID,
        vars: {
          brand: brand
        },
        analytics: {
          langFuse: {
            userId: `query-flow-${brand}`
          }
        }
      }
    };

    flowiseData.overrideConfig = {
      ...flowiseData.overrideConfig,
      ...flowiseOverrideObject
    };
    Logger.info(
      `sendQueryToFlowise for brand ${brand}: ${url}  \n${JSON.stringify(
        flowiseData
      )}`
    );

    const response = await fetch(url, {
      method: 'POST',
      headers: {
        'Content-Type': 'application/json'
      },
      body: JSON.stringify(flowiseData)
    });
    const endTime = Date.now();
    const executionTime = endTime - startTime;
    Logger.info(`Execution time for sendQueryToFlowise: ${executionTime}ms`);
    const result = await response.json();
    Logger.info(`Response data:${JSON.stringify(result)}`);
    return result;
  }
  catch (error) {
    const customError = createCustomError(
      error,
      'sendQueryToFlowise',
      `Error in retrieving response from flowise`,
      ERROR_CODE?.P1_ERROR_RETRIEVING_CHAT_MESSAGE?.errorCode,
      ERROR_CODE?.P1_ERROR_RETRIEVING_CHAT_MESSAGE?.statusCode
    );

    Logger.error(errorSerializer(customError));
    throw error;
  }
}

