setConfig(req, res, next) {
    try {
      const clientIp = req.headers['x-real-ip'] || req.headers['x-forwarded-for'] || req.connection.remoteAddress;
      const clientPort = req.headers['x-forwarded-port'] || req.connection.remotePort;
      Logger.info(`Request coming from Client IP: ${clientIp}, Port: ${clientPort}`);
      const origin = req.headers.origin || '';

      if (origin && origin in this.originMapping) {
        // Assign the configId and proceed to the next middleware
        const configId = this.originMapping[origin];
        Logger.info(
          `Request is from origin: ${origin}, using config id: ${configId}`
        );
        // Pass the configId to the next middleware
        req.configId = configId;
        next();
      } else {
        // Origin is invalid, return 401 Unauthorized
        Logger.info('Mandatory header - origin is either missing or invalid');
        res.sendStatus(401);
      }
    } catch (err) {

      const customError = createCustomError(err, 'setConfig', ERROR_CODE?.P1_CONFIGURATION_ERROR?.errorMessage, ERROR_CODE?.P1_CONFIGURATION_ERROR?.errorCode, ERROR_CODE?.P1_CONFIGURATION_ERROR?.statusCode);
      Logger.error(errorSerializer(customError));
      res.sendStatus(401);
    }
  }

