    const updatedSessions = existingUserObject.sessions.map((s) =>
      s.sessionID === sessionID
        ? { ...s, chatHistory: [...s.chatHistory, ...chatHistory] }
        : s
    );
    await this.updateUserObjectInStore(clientID, { sessions: updatedSessions });
    return updatedSessions.find((s) => s.sessionID === sessionID)?.chatHistory || [];
