public async updateUserObject(
    clientID,
    userUUID,
    sessionID,
    chatHistory
  ): Promise<z.infer<typeof chatHistorySchema> | Error> {
    const existingUserObject = await this.getExistingUserObject(
      clientID,
      userUUID
    );
    if (!existingUserObject) {
      throw new Error('User object not found');
    }
    const updatedSessions = existingUserObject.sessions.map(s =>
      s.sessionID === sessionID
        ? { ...s, chatHistory: s.chatHistory.concat(chatHistory) }
        : s
    );
    const fullChatHistory = updatedSessions.find(
