function isNumericString(str) {
  const numericRegex = /^\d+$/;
  return numericRegex.test(str);
}

function isValidUUID(uuid) {
  const uuidRegex =
    /^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$/i;
  return uuidRegex.test(uuid);
}

function validateInput(sessionID, clientID) {
  if (!isValidUUID(sessionID) || !isNumericString(clientID)) {
    const errorObject = new Error("Invalid session id or client id ");

    const customError = createCustomError(errorObject, 'validateInput', `Invalid sessionID or clientID detected: sessionID=${sessionID}, clientID=${clientID}`, ERROR_CODE?.P2_INVALID_SESSION_ID_CLIENTID?.errorCode, ERROR_CODE?.P2_INVALID_SESSION_ID_CLIENTID?.statusCode);

    Logger.error(errorSerializer(customError));
    return false;
  }
  return true;
}

async function processFlowiseQuery(
  flowiseConfig,
  query,
  sessionID,
  brand,
  res
) {
  try {
    const result = await sendQueryToFlowise(
      flowiseConfig.flowiseHost + flowiseConfig.chat,
      query,
      sessionID,
      brand
    );
    if (result.error) {

      const customError = createCustomError(result.error, 'processFlowiseQuery', `Error in chat message: ${result.error}`, ERROR_CODE?.P1_ERROR_CHAT_MESSAGE?.errorCode, ERROR_CODE?.P1_ERROR_CHAT_MESSAGE?.statusCode);

      Logger.error(errorSerializer(customError));
      res.status(200).json({
        response: {
          text: result.error,
          serviceStatus: serviceStatus.getStatus()
        }
      });
      return null;
    }
    return result;
  } catch (error) {

    const customError = createCustomError(error,
      'processFlowiseQuery',
      `Error while retrieving chat message: ${JSON.stringify(error.response?.data || error)}`,
      ERROR_CODE?.P1_ERROR_RETRIEVING_CHAT_MESSAGE?.errorCode,
      ERROR_CODE?.P1_ERROR_RETRIEVING_CHAT_MESSAGE?.statusCode
    );
    Logger.error(errorSerializer(customError));
    res.status(500).json({
      text: 'I am sorry, I can\'t respond to this. Please try again later.',
    });
    return null;
  }
}

async function generateSuggestions(flowiseConfig, input, brand) {
  let suggestions = [];
  try {
    if (input) {
      const suggestionsObject = (
        await suggestionPromptsQuery(
          flowiseConfig.flowiseHost + flowiseConfig.suggestionPrompts,
          input,
          brand
        )
      )?.json;
      const suggestionsEntries = Object.fromEntries(
        Object.entries(suggestionsObject).map(([key, value]) => [
          key,
          (value as string).replace(/['"]+/g, '')
        ])
      );
      suggestions = Object.values(suggestionsEntries);
    }
  } catch (error) {

    const customError = createCustomError(error,
      'generateSuggestions',
      `Error in generating suggestion: ${error}`,
      ERROR_CODE?.P2_ERROR_SUGGESTION_FLOW?.errorCode,
      ERROR_CODE?.P2_ERROR_SUGGESTION_FLOW?.statusCode
    );
    Logger.error(errorSerializer(customError));
  }
  return suggestions;
}

async function updateUserSessionAndObject(
  {
    clientID,
    userUUID,
    sessionID,
    sessionObject = {},
    context = {}
  },
  res
) {
  const existingUserObject = await userObject.getExistingUserObject(
    clientID,
    userUUID
  );
  if (!existingUserObject) {
    const errorObject = new Error("User object not found, please reinitialize the session");

    const customError = createCustomError(errorObject, 'updateUserSessionAndObject', `User object not found, please reinitialize the session`, ERROR_CODE?.P2_INVALID_SESSION_ID_CLIENTID?.errorCode, ERROR_CODE?.P2_INVALID_SESSION_ID_CLIENTID?.statusCode);

    Logger.error(errorSerializer(customError));

    res.status(400).json({
      error: 'User object not found, please reinitialize the session'
    });
    return false;
  }
  const updatedSessions = existingUserObject.sessions.map(s =>
    s.sessionID === sessionID
      ? {
        ...s,
        ...sessionObject
      }
      : s
  );
  const updatedUserObject = {
    ...existingUserObject,
    sessions: updatedSessions,
    context: { ...existingUserObject.context, ...context }
  };
  const parsedUserObject = userObject.validateUserObject(updatedUserObject);
  await userObject.updateUserObjectInStore(clientID, parsedUserObject);
  return true;
}

