async function flattenChatHistory(chatHistory) {
  return chatHistory.map(message => {
    if (message.type === 'apiMessage') {
      return { role: 'system', content: message.message };
    } else if (message.type === 'userMessage') {
      const userMessage = message.message?.split('###\n\n').pop();
      return { role: 'user', content: userMessage };
    }
  });
}

async function flattenChatHistoryToString(chatHistory) {
  return chatHistory
    .map(message => {
      if (message.type === 'apiMessage') {
        return `agent: ${message.message}`;
      } else if (message.type === 'userMessage') {
        const userMessage = message.message?.split('###\n\n').pop();
        return `user: ${userMessage}`;
      }
    })
    .join('\n');
}

function mapTopActions(response) {
  return {
    top_actions: response.top_actions.map(actionObj => ({
      action: actionMapping[actionObj.action] || actionObj.action,
      probability: actionObj.probability
    })),
    user_category: response.user_category,
    model_name: response.model_name,
    model_year: response.model_year,
    zip_code: response.zip_code
  };
}

async function generateNextBestActionsV2(
  fullChatHistory,
  current_question,
  sessionID, clientId
) {
  const apiUrl = process.env.NEXT_BEST_ACTION_URI + '/api/v1/predict';

  const requestData = {
    chat_history: fullChatHistory,
    current_question: current_question
  };

  try {
    const response = await axios.post(apiUrl, requestData, {
      headers: {
        'Content-Type': 'application/json'
      }
    });

    const { user_category, model_name, model_year, zip_code, top_actions, full_actions } =
      response.data;

    const formattedFullActions = Array.isArray(full_actions)
      ? full_actions.map(item => {

        return {
          action: item[0],
          probability: item[1]
        };
      })
      : [];

    // Prepare chat insight data

    const chatInsight: any = {};
    if (user_category !== null) chatInsight.user_category = user_category;
    if (Array.isArray(model_name)) chatInsight.model_name = model_name;
    if (Array.isArray(model_year)) chatInsight.model_year = model_year;
    if (zip_code !== null) chatInsight.zip_code = zip_code;
    if (formattedFullActions !== null) chatInsight.full_actions = formattedFullActions;
    Logger.info(`Extracted Chat Insight: ${JSON.stringify(chatInsight)}`);

    await userObject.addChatInsight(sessionID, chatInsight, clientId);
    Logger.info(`Chat insight updated for sessionID: ${sessionID}`);

    const mappedResponse = mapTopActions({
      top_actions,
      user_category,
      model_name,
      model_year,
      zip_code,
      full_actions: formattedFullActions
    });

    return mappedResponse.top_actions.map(a => a.action);
  } catch (error) {

    const customError = createCustomError(error,
      'generateNextBestActions',
      `Error in next best CTAs: ${error}`,
      ERROR_CODE?.P2_ERROR_IN_NEXT_BEST_ACTION?.errorCode,
      ERROR_CODE?.P2_ERROR_IN_NEXT_BEST_ACTION?.statusCode
    );
    Logger.error(errorSerializer(customError));
  }
}

async function getDatabaseInstance(): Promise<User | DynamoUser> {
  switch (process.env.DATABASE_TYPE) {
    case "DYNAMODB":
      return await DynamoUser.instance;
    case "MONGODB":
      return await User.instance;
    default:
      throw new Error(`Unsupported DATABASE_TYPE: ${process.env.DATABASE_TYPE}`);
  }
}

async function initialize() {
  userObject = await getDatabaseInstance();
}

async function sendUserActionUpdate(chatInsight, mappedAction, updatedCost) {
  try {
    const formattedFullActions = Array.isArray(chatInsight.full_actions)
      ? chatInsight.full_actions.map(item => [item.action, item.probability])
      : [];

    const payload = {
      user_category: chatInsight.user_category,
      model_name: chatInsight.model_name,
      model_year: String(chatInsight.model_year),
      vehicle_types: 'Minivan',
      action: mappedAction,
      cost: updatedCost,
      full_actions: formattedFullActions

    };
    Logger.info(`Sending API request with data: ${JSON.stringify(payload)}`);

    const apiUrl = process.env.NEXT_BEST_ACTION_URI + '/api/v1/update';
    const response = await axios.post(apiUrl, payload, {
      headers: { 'Content-Type': 'application/json' }
    });

    Logger.info(`API Response: ${JSON.stringify(response.data)}`);

    return response.data;
  } catch (error) {

    const customError = createCustomError(error, 'sendUserActionUpdate', `Error in sendUserActionUpdate: ${error.message}`, ERROR_CODE?.P1_INITIALIZATION_ERROR?.errorCode, ERROR_CODE?.P1_INITIALIZATION_ERROR?.statusCode);

    Logger.error(errorSerializer(customError));

  }
}
